import { BaseMovementBehavior } from "./BaseMovementBehavior";
import { Enemy } from "../entities/Enemy";

// Standard behavior: move towards player and attack when in range

export class ChaseBehavior extends BaseMovementBehavior {
  constructor(
    attackRange: number,
    moveSpeed: number,
    canAttackWhileMoving: boolean = false
  ) {
    super(attackRange, moveSpeed, canAttackWhileMoving);
  }

  update(
    enemy: Enemy,
    playerX: number,
    playerY: number,
    deltaTime: number
  ): { targetX: number; targetY: number; shouldAttack: boolean } {
    const distance = this.getDistanceToPlayer(enemy, playerX, playerY);
    const shouldAttack = this.shouldAttack(enemy, playerX, playerY);

    // If we can attack while moving or we're not in attack range, keep moving
    if (this.canAttackWhileMoving || !shouldAttack) {
      return { targetX: playerX, targetY: playerY, shouldAttack };
    }

    // Stop and attack
    return { targetX: enemy.x, targetY: enemy.y, shouldAttack: true };
  }

  getType(): string {
    return "chase";
  }
}
