import React from 'react';

export interface ButtonProps {
  children: React.ReactNode;
  onClick?: () => void;
  variant?: 'primary' | 'secondary' | 'accent' | 'danger' | 'success';
  size?: 'small' | 'medium' | 'large';
  disabled?: boolean;
  fullWidth?: boolean;
  className?: string;
  style?: React.CSSProperties;
  type?: 'button' | 'submit' | 'reset';
}

export const Button: React.FC<ButtonProps> = ({
  children,
  onClick,
  variant = 'primary',
  size = 'medium',
  disabled = false,
  fullWidth = false,
  className = '',
  style = {},
  type = 'button',
}) => {
  const variantStyles = {
    primary: {
      backgroundColor: '#9a9a9a',
      color: '#ffffff',
      '&:hover': { backgroundColor: '#aaaaaa' },
      '&:active': { backgroundColor: '#8a8a8a' },
    },
    secondary: {
      backgroundColor: '#7a7a7a',
      color: '#ffffff',
      '&:hover': { backgroundColor: '#8a8a8a' },
      '&:active': { backgroundColor: '#6a6a6a' },
    },
    accent: {
      backgroundColor: '#aaaaaa',
      color: '#ffffff',
      '&:hover': { backgroundColor: '#bababa' },
      '&:active': { backgroundColor: '#9a9a9a' },
    },
    danger: {
      backgroundColor: '#8a2a2a',
      color: '#ffffff',
      '&:hover': { backgroundColor: '#9a3a3a' },
      '&:active': { backgroundColor: '#7a1a1a' },
    },
    success: {
      backgroundColor: '#2a8a2a',
      color: '#ffffff',
      '&:hover': { backgroundColor: '#3a9a3a' },
      '&:active': { backgroundColor: '#1a7a1a' },
    },
  };

  const sizeStyles = {
    small: {
      padding: '6px 12px',
      fontSize: '12px',
      minHeight: '28px',
    },
    medium: {
      padding: '8px 16px',
      fontSize: '14px',
      minHeight: '36px',
    },
    large: {
      padding: '12px 24px',
      fontSize: '16px',
      minHeight: '44px',
    },
  };

  const buttonStyle: React.CSSProperties = {
    ...variantStyles[variant],
    ...sizeStyles[size],
    width: fullWidth ? '100%' : 'auto',
    border: 'none',
    cursor: disabled ? 'not-allowed' : 'pointer',
    opacity: disabled ? 0.6 : 1,
    transition: 'background-color 0.2s ease',
    textTransform: 'uppercase',
    fontWeight: 'bold',
    letterSpacing: '0.5px',
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    ...style,
  };

  const handleClick = (e: React.MouseEvent) => {
    if (!disabled && onClick) {
      onClick();
    }
  };

  const handleMouseEnter = (e: React.MouseEvent) => {
    if (!disabled) {
      const target = e.currentTarget as HTMLElement;
      const hoverColor = variantStyles[variant]['&:hover'].backgroundColor;
      target.style.backgroundColor = hoverColor;
    }
  };

  const handleMouseLeave = (e: React.MouseEvent) => {
    if (!disabled) {
      const target = e.currentTarget as HTMLElement;
      target.style.backgroundColor = variantStyles[variant].backgroundColor;
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!disabled) {
      const target = e.currentTarget as HTMLElement;
      const activeColor = variantStyles[variant]['&:active'].backgroundColor;
      target.style.backgroundColor = activeColor;
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
    if (!disabled) {
      const target = e.currentTarget as HTMLElement;
      const hoverColor = variantStyles[variant]['&:hover'].backgroundColor;
      target.style.backgroundColor = hoverColor;
    }
  };

  return (
    <button
      type={type}
      className={`ui-button ui-button-${variant} ui-button-${size} ${className}`}
      style={buttonStyle}
      onClick={handleClick}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      onMouseDown={handleMouseDown}
      onMouseUp={handleMouseUp}
      disabled={disabled}
    >
      {children}
    </button>
  );
};
