import { BaseMovementBehavior } from "./BaseMovementBehavior";
import { Enemy } from "../entities/Enemy";

// Circle behavior: orbit around the player at a certain distance

export class CircleBehavior extends BaseMovementBehavior {
  private initialOrbitRadius: number;
  private currentOrbitRadius: number;
  private orbitSpeed: number;
  private currentAngle1: number = 0;
  private currentAngle2: number = Math.PI; // Start opposite to first point
  private startTime: number = 0;
  private radiusShrinkDuration: number = 20000; // 20 seconds in milliseconds
  private minRadius: number = 300; // Minimum radius after shrinking
  private isRadiusShrinking: boolean = false;

  // Circle cage system
  private cageCenterX: number = 0;
  private cageCenterY: number = 0;
  private cageRadius: number = 0;
  private cageInitialized: boolean = false;

  constructor(
    attackRange: number,
    moveSpeed: number,
    orbitRadius: number,
    orbitSpeed: number = 1,
    canAttackWhileMoving: boolean = true,
    enableRadiusShrinking: boolean = false
  ) {
    super(attackRange, moveSpeed, canAttackWhileMoving);
    this.initialOrbitRadius = orbitRadius;
    this.currentOrbitRadius = orbitRadius;
    this.orbitSpeed = orbitSpeed;
    this.isRadiusShrinking = enableRadiusShrinking;
  }

  update(
    enemy: Enemy,
    playerX: number,
    playerY: number,
    deltaTime: number
  ): { targetX: number; targetY: number; shouldAttack: boolean } {
    const distance = this.getDistanceToPlayer(enemy, playerX, playerY);
    const shouldAttack = this.shouldAttack(enemy, playerX, playerY);

    // Initialize start time if not set
    if (this.startTime === 0) {
      this.startTime = Date.now();
    }

    // Update radius if shrinking is enabled
    if (this.isRadiusShrinking) {
      const elapsedTime = Date.now() - this.startTime;
      const progress = Math.min(elapsedTime / this.radiusShrinkDuration, 1);
      this.currentOrbitRadius =
        this.initialOrbitRadius -
        (this.initialOrbitRadius - this.minRadius) * progress;
    }

    // Initialize circle cage
    if (!this.cageInitialized) {
      this.cageCenterX = playerX;
      this.cageCenterY = playerY;
      this.cageRadius = 200; // Fixed 200px radius cage
      this.cageInitialized = true;
    }

    // Update circle cage - only move if player pushes against the boundary
    this.updateCircleCage(playerX, playerY);

    // Update orbit angles - convert deltaTime from milliseconds to seconds
    this.currentAngle1 += this.orbitSpeed * (deltaTime / 1000) * 6; // 3x faster than before
    this.currentAngle2 += this.orbitSpeed * (deltaTime / 1000) * 6; // 3x faster than before

    // Calculate two orbit positions relative to cage center (not player)
    const orbitX1 =
      this.cageCenterX + Math.cos(this.currentAngle1) * this.currentOrbitRadius;
    const orbitY1 =
      this.cageCenterY + Math.sin(this.currentAngle1) * this.currentOrbitRadius;

    const orbitX2 =
      this.cageCenterX + Math.cos(this.currentAngle2) * this.currentOrbitRadius;
    const orbitY2 =
      this.cageCenterY + Math.sin(this.currentAngle2) * this.currentOrbitRadius;

    // Find which orbit point is closest to the enemy
    const distToPoint1 = Math.sqrt(
      Math.pow(enemy.x - orbitX1, 2) + Math.pow(enemy.y - orbitY1, 2)
    );
    const distToPoint2 = Math.sqrt(
      Math.pow(enemy.x - orbitX2, 2) + Math.pow(enemy.y - orbitY2, 2)
    );

    // Return the closest orbit point
    if (distToPoint1 <= distToPoint2) {
      return { targetX: orbitX1, targetY: orbitY1, shouldAttack };
    } else {
      return { targetX: orbitX2, targetY: orbitY2, shouldAttack };
    }
  }

  // Update circle cage - only moves when player pushes against boundary
  private updateCircleCage(playerX: number, playerY: number): void {
    const distanceFromCageCenter = Math.sqrt(
      Math.pow(playerX - this.cageCenterX, 2) +
        Math.pow(playerY - this.cageCenterY, 2)
    );

    // If player is outside the cage boundary, push the cage
    if (distanceFromCageCenter > this.cageRadius) {
      // Calculate how far outside the player is
      const pushDistance = distanceFromCageCenter - this.cageRadius;

      // Calculate direction from cage center to player
      const directionX = (playerX - this.cageCenterX) / distanceFromCageCenter;
      const directionY = (playerY - this.cageCenterY) / distanceFromCageCenter;

      // Move cage center in that direction
      this.cageCenterX += directionX * pushDistance;
      this.cageCenterY += directionY * pushDistance;
    }
  }

  getType(): string {
    return "circle";
  }

  // Helper method to get both orbit points for visualization
  getOrbitPoints(
    playerX: number,
    playerY: number
  ): { point1: { x: number; y: number }; point2: { x: number; y: number } } {
    const orbitX1 =
      this.cageCenterX + Math.cos(this.currentAngle1) * this.currentOrbitRadius;
    const orbitY1 =
      this.cageCenterY + Math.sin(this.currentAngle1) * this.currentOrbitRadius;

    const orbitX2 =
      this.cageCenterX + Math.cos(this.currentAngle2) * this.currentOrbitRadius;
    const orbitY2 =
      this.cageCenterY + Math.sin(this.currentAngle2) * this.currentOrbitRadius;

    return {
      point1: { x: orbitX1, y: orbitY1 },
      point2: { x: orbitX2, y: orbitY2 },
    };
  }

  // Helper method to get cage information for visualization
  getCageInfo(): { centerX: number; centerY: number; radius: number } {
    return {
      centerX: this.cageCenterX,
      centerY: this.cageCenterY,
      radius: this.cageRadius,
    };
  }
}
