import React from 'react';

interface PlayerStatsWidgetProps {
  level: number;
  xp: number;
  xpToNext: number;
  hp: number;
  maxHp: number;
  gold: number;
  isVisible: boolean;
}

const PlayerStatsWidget: React.FC<PlayerStatsWidgetProps> = ({
  level,
  xp,
  xpToNext,
  hp,
  maxHp,
  gold,
  isVisible
}) => {
  if (!isVisible) return null;

  const xpProgress = xpToNext > 0 ? (xp / xpToNext) * 100 : 0;
  const hpProgress = maxHp > 0 ? (hp / maxHp) * 100 : 0;

  return (
    <div
      style={{
        position: 'fixed',
        top: '20px',
        left: '50%',
        transform: 'translateX(-50%)',
        zIndex: 100,
        display: 'flex',
        flexDirection: 'column',
        gap: '8px',
        alignItems: 'center',
        pointerEvents: 'none',
      }}
    >
      {/* Level Display */}
      <div
        style={{
          color: '#ffffff',
          fontSize: '14px',
          fontWeight: 'bold',
          textShadow: '0 2px 4px rgba(0,0,0,0.8)',
          letterSpacing: '0.5px',
          textAlign: 'center',
        }}
      >
        LVL {level}
      </div>

      {/* XP Bar */}
      <div
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '3px',
          alignItems: 'center',
          minWidth: '160px',
        }}
      >
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            width: '100%',
          }}
        >
          <span
            style={{
              color: '#ffffff',
              fontSize: '11px',
              fontWeight: 'bold',
              textShadow: '0 1px 2px rgba(0,0,0,0.8)',
            }}
          >
            XP
          </span>
          <span
            style={{
              color: '#44aaff',
              fontSize: '11px',
              fontWeight: 'bold',
              textShadow: '0 1px 2px rgba(0,0,0,0.8)',
            }}
          >
            {xp}/{xpToNext}
          </span>
        </div>
        <div
          style={{
            background: 'rgba(255,255,255,0.2)',
            borderRadius: '4px',
            height: '6px',
            width: '100%',
            overflow: 'hidden',
            position: 'relative',
          }}
        >
          <div
            style={{
              background: '#44aaff',
              height: '100%',
              width: `${xpProgress}%`,
              borderRadius: '4px',
              transition: 'width 0.3s ease',
            }}
          />
        </div>
      </div>

      {/* Health Bar */}
      <div
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '3px',
          alignItems: 'center',
          minWidth: '160px',
        }}
      >
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            width: '100%',
          }}
        >
          <span
            style={{
              color: '#ffffff',
              fontSize: '11px',
              fontWeight: 'bold',
              textShadow: '0 1px 2px rgba(0,0,0,0.8)',
            }}
          >
            HP
          </span>
          <span
            style={{
              color: hpProgress > 50 ? '#4ecdc4' : hpProgress > 25 ? '#ffd700' : '#ff6b6b',
              fontSize: '11px',
              fontWeight: 'bold',
              textShadow: '0 1px 2px rgba(0,0,0,0.8)',
            }}
          >
            {hp}/{maxHp}
          </span>
        </div>
        <div
          style={{
            background: 'rgba(255,255,255,0.2)',
            borderRadius: '4px',
            height: '6px',
            width: '100%',
            overflow: 'hidden',
            position: 'relative',
          }}
        >
          <div
            style={{
              background: hpProgress > 50 
                ? 'linear-gradient(90deg, #4ecdc4, #44a08d)' 
                : hpProgress > 25 
                ? 'linear-gradient(90deg, #ffd700, #ffed4e)' 
                : 'linear-gradient(90deg, #ff6b6b, #ee5a24)',
              height: '100%',
              width: `${hpProgress}%`,
              borderRadius: '4px',
              transition: 'width 0.3s ease, background 0.3s ease',
            }}
          />
        </div>
      </div>

      {/* Gold Display */}
      <div
        style={{
          color: '#ffd700',
          fontSize: '14px',
          fontWeight: 'bold',
          textShadow: '0 2px 4px rgba(0,0,0,0.8)',
          letterSpacing: '0.5px',
          display: 'flex',
          alignItems: 'center',
          gap: '6px',
        }}
      >
        <span style={{ fontSize: '16px' }}>💰</span>
        {gold.toLocaleString()}
      </div>
    </div>
  );
};

export default PlayerStatsWidget;
