import { BehaviorManager } from "../behaviours/BehaviorManager";
import { CircleBehavior } from "../behaviours/CircleBehavior";
import { SegmentedEntity } from "./SegmentedEntity";

export class GlassLeviathanEnemy extends SegmentedEntity {
  behaviorManager: BehaviorManager;

  constructor(
    hp: number,
    armor: number,
    moveSpeed: number,
    attackDamage: number,
    attackSpeed: number,
    attackRange: number,
    magicResist: number,
    magicPower: number,
    evasion: number,
    xp: number,
    projectileScale: number,
    projectileSpeed: number
  ) {
    super(
      "glass_leviathan",
      32, // 32 segments for glass leviathan
      220, // segment radius (match enemy radius)
      0xe6e6fa, // lavender color
      hp,
      armor,
      moveSpeed,
      attackDamage,
      attackSpeed,
      attackRange,
      magicResist,
      magicPower,
      0,
      0,
      0,
      0,
      0,
      0,
      0,
      0,
      0,
      evasion,
      1,
      1,
      0,
      1,
      false
    );

    this.behaviorManager = new BehaviorManager(
      new CircleBehavior(this.attackRange, this.moveSpeed, 600, 0.1, true, true)
    );
  }
}
