import { MovementBehavior } from "./MovementBehavior";
import { Enemy } from "../entities/Enemy";

// Behavior manager for enemies

export class BehaviorManager {
  private currentBehavior: MovementBehavior;

  constructor(defaultBehavior: MovementBehavior) {
    this.currentBehavior = defaultBehavior;
  }

  update(
    enemy: Enemy,
    playerX: number,
    playerY: number,
    deltaTime: number
  ): { targetX: number; targetY: number; shouldAttack: boolean } {
    return this.currentBehavior.update(enemy, playerX, playerY, deltaTime);
  }

  getCurrentBehaviorType(): string {
    return this.currentBehavior.getType();
  }

  getCurrentBehavior(): MovementBehavior {
    return this.currentBehavior;
  }
}
