import React from 'react';
import { BasePanel, BasePanelProps } from './BasePanel';

export interface PanelProps extends BasePanelProps {
  title?: string;
  variant?: 'primary' | 'secondary' | 'accent' | 'dark';
  size?: 'small' | 'medium' | 'large';
  fullWidth?: boolean;
  fullHeight?: boolean;
}

export const Panel: React.FC<PanelProps> = ({
  title,
  variant = 'primary',
  size = 'medium',
  fullWidth = false,
  fullHeight = false,
  children,
  className = '',
  style = {},
  ...baseProps
}) => {
  const variantStyles = {
    primary: { backgroundColor: '#8a8a8a' },
    secondary: { backgroundColor: '#7a7a7a' },
    accent: { backgroundColor: '#9a9a9a' },
    dark: { backgroundColor: '#5a5a5a' },
  };

  const sizeStyles = {
    small: { padding: '8px' },
    medium: { padding: '12px' },
    large: { padding: '16px' },
  };

  const panelStyle: React.CSSProperties = {
    ...variantStyles[variant],
    ...sizeStyles[size],
    width: fullWidth ? '100%' : 'auto',
    height: fullHeight ? '100%' : 'auto',
    display: 'flex',
    flexDirection: 'column',
    ...style,
  };

  const titleStyle: React.CSSProperties = {
    fontSize: size === 'large' ? '18px' : size === 'medium' ? '16px' : '14px',
    fontWeight: 'bold',
    marginBottom: '8px',
    color: '#ffffff',
    textTransform: 'uppercase',
    letterSpacing: '1px',
  };

  return (
    <BasePanel
      className={`panel panel-${variant} panel-${size} ${className}`}
      style={panelStyle}
      {...baseProps}
    >
      {title && <div style={titleStyle}>{title}</div>}
      <div style={{ flex: 1 }}>{children}</div>
    </BasePanel>
  );
};
