import React, { useEffect, useState } from 'react';

interface MainMenuProps {
  onStartGame: () => void;
}

const MainMenu: React.FC<MainMenuProps> = ({ onStartGame }) => {
  const [balls, setBalls] = useState<Array<{id: number, x: number, y: number, size: number, speed: number}>>([]);

  useEffect(() => {
    // Create initial balls
    const initialBalls = Array.from({ length: 12 }, (_, i) => ({
      id: i,
      x: Math.random() * window.innerWidth,
      y: Math.random() * window.innerHeight,
      size: Math.random() * 60 + 30, // 30-90px (50% larger)
      speed: Math.random() * 0.75 + 0.3, // 0.3-1.05 speed (50% faster)
    }));
    setBalls(initialBalls);

    // Animation loop for balls moving toward center
    const animateBalls = () => {
      setBalls(prevBalls => 
        prevBalls.map(ball => {
          const centerX = window.innerWidth / 2;
          const centerY = window.innerHeight / 2;
          
          // Calculate direction toward center
          const dx = centerX - ball.x;
          const dy = centerY - ball.y;
          const distance = Math.sqrt(dx * dx + dy * dy);
          
          // Move toward center
          const newX = ball.x + (dx / distance) * ball.speed;
          const newY = ball.y + (dy / distance) * ball.speed;
          
          // If ball gets too close to center, reset to edge
          if (distance < 50) {
            const angle = Math.random() * Math.PI * 2;
            const edgeDistance = Math.max(window.innerWidth, window.innerHeight) * 0.6;
            return {
              ...ball,
              x: centerX + Math.cos(angle) * edgeDistance,
              y: centerY + Math.sin(angle) * edgeDistance,
            };
          }
          
          return { ...ball, x: newX, y: newY };
        })
      );
    };

    const interval = setInterval(animateBalls, 16); // ~60fps

    // Add keyboard event listener for any key to start game
    const handleKeyPress = (event: KeyboardEvent) => {
      onStartGame();
    };

    window.addEventListener('keydown', handleKeyPress);

    return () => {
      clearInterval(interval);
      window.removeEventListener('keydown', handleKeyPress);
    };
  }, [onStartGame]);

  return (
    <div
      style={{
        position: 'absolute',
        top: 0,
        left: 0,
        width: '100vw',
        height: '100vh',
        background: '#d1bd9b', // Exact same as game background
        zIndex: 3000,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        overflow: 'hidden',
      }}
    >
      {/* Grid Background - matching game tilemap style */}
      <div
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          width: '100%',
          height: '100%',
          backgroundImage: `
            linear-gradient(rgba(35, 35, 43, 0.3) 1px, transparent 1px),
            linear-gradient(90deg, rgba(35, 35, 43, 0.3) 1px, transparent 1px)
          `,
          backgroundSize: '64px 64px',
          backgroundPosition: '0 0',
        }}
      />
      {/* Grid borders - matching game border style */}
      <div
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          width: '100%',
          height: '100%',
          backgroundImage: `
            linear-gradient(rgba(68, 68, 102, 0.1) 1px, transparent 1px),
            linear-gradient(90deg, rgba(68, 68, 102, 0.1) 1px, transparent 1px)
          `,
          backgroundSize: '64px 64px',
          backgroundPosition: '0 0',
        }}
      />

      {/* Transparent balls pulling toward center - 50% more noticeable */}
      {balls.map(ball => (
        <div
          key={ball.id}
          style={{
            position: 'absolute',
            left: ball.x,
            top: ball.y,
            width: ball.size,
            height: ball.size,
            background: 'radial-gradient(circle, rgba(255,255,255,0.225) 0%, rgba(255,255,255,0.075) 70%, transparent 100%)', // 50% more opacity
            borderRadius: '50%',
            transform: 'translate(-50%, -50%)',
            pointerEvents: 'none',
          }}
        />
      ))}

      {/* Character representation in center - exact same as game */}
      <div
        style={{
          position: 'absolute',
          top: '50%',
          left: '50%',
          transform: 'translate(-50%, -50%)',
          width: '40px',
          height: '40px',
          background: '#44aaff', // Exact same blue as game player
          borderRadius: '50%',
        }}
      />

      {/* Floating "PRESS TO START" button */}
      <div
        style={{
          position: 'absolute',
          bottom: '33.33%',
          left: '50%',
          transform: 'translateX(-50%)',
          zIndex: 10,
        }}
      >
        <button
          onClick={onStartGame}
          className="start-button"
          style={{
            background: 'none',
            border: 'none',
            color: '#ffffff',
            fontSize: '2rem',
            fontWeight: 'bold',
            textTransform: 'uppercase',
            letterSpacing: '4px',
            textShadow: '0 2px 8px rgba(0,0,0,0.8), 0 0 20px rgba(255,255,255,0.5)',
            cursor: 'pointer',
            padding: '20px 40px',
            borderRadius: '8px',
            transition: 'all 0.3s ease',
            animation: 'fadeInUp 1s ease-out, glow 2s ease-in-out infinite',
          }}
        >
          PRESS TO START
        </button>
      </div>

      {/* Game title */}
      <div
        style={{
          position: 'absolute',
          top: '10%',
          left: '50%',
          transform: 'translateX(-50%)',
          textAlign: 'center',
          zIndex: 10,
        }}
      >
        <h1
          style={{
            fontSize: '3.5rem',
            fontWeight: 'bold',
            color: '#ffffff',
            textTransform: 'uppercase',
            letterSpacing: '6px',
            margin: '0',
            textShadow: '0 4px 16px rgba(0,0,0,0.8), 0 0 30px rgba(255,255,255,0.3)',
            animation: 'fadeInDown 1s ease-out',
          }}
        >
          CIRCLE JERK
        </h1>
      </div>

      {/* Controls Panel - same position as in game */}
      <div
        style={{
          position: 'absolute',
          left: '60px',
          top: '50%',
          transform: 'translateY(-50%)',
          zIndex: 10,
          pointerEvents: 'none',
        }}
      >
        <div
          style={{
            display: 'flex',
            gap: '24px',
            alignItems: 'flex-start',
          }}
        >
          {/* Button Box - Left Side */}
          <div
            style={{
              display: 'flex',
              flexDirection: 'column',
              gap: '12px',
              alignItems: 'flex-end',
            }}
          >
            <div style={{ display: 'flex', alignItems: 'center' }}>
              <div style={{
                background: 'linear-gradient(145deg, #e0e0e0, #d0d0d0)',
                border: '2px solid #999',
                borderRadius: '6px',
                padding: '8px',
                width: '32px',
                height: '32px',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                boxShadow: 'inset 0 1px 3px rgba(255,255,255,0.3), 0 2px 4px rgba(0,0,0,0.2)',
                color: '#000000',
                fontWeight: '900',
                letterSpacing: '1px',
                fontSize: '1.1rem',
                textShadow: 'none',
                marginRight: '4px',
              }}>W</div>
              <div style={{
                background: 'linear-gradient(145deg, #e0e0e0, #d0d0d0)',
                border: '2px solid #999',
                borderRadius: '6px',
                padding: '8px',
                width: '32px',
                height: '32px',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                boxShadow: 'inset 0 1px 3px rgba(255,255,255,0.3), 0 2px 4px rgba(0,0,0,0.2)',
                color: '#000000',
                fontWeight: '900',
                letterSpacing: '1px',
                fontSize: '1.1rem',
                textShadow: 'none',
                marginRight: '4px',
              }}>A</div>
              <div style={{
                background: 'linear-gradient(145deg, #e0e0e0, #d0d0d0)',
                border: '2px solid #999',
                borderRadius: '6px',
                padding: '8px',
                width: '32px',
                height: '32px',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                boxShadow: 'inset 0 1px 3px rgba(255,255,255,0.3), 0 2px 4px rgba(0,0,0,0.2)',
                color: '#000000',
                fontWeight: '900',
                letterSpacing: '1px',
                fontSize: '1.1rem',
                textShadow: 'none',
                marginRight: '4px',
              }}>S</div>
              <div style={{
                background: 'linear-gradient(145deg, #e0e0e0, #d0d0d0)',
                border: '2px solid #999',
                borderRadius: '6px',
                padding: '8px',
                width: '32px',
                height: '32px',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                boxShadow: 'inset 0 1px 3px rgba(255,255,255,0.3), 0 2px 4px rgba(0,0,0,0.2)',
                color: '#000000',
                fontWeight: '900',
                letterSpacing: '1px',
                fontSize: '1.1rem',
                textShadow: 'none',
                marginRight: '4px',
              }}>D</div>
            </div>
            <div style={{
              background: 'linear-gradient(145deg, #e0e0e0, #d0d0d0)',
              border: '2px solid #999',
              borderRadius: '6px',
              padding: '6px 12px',
              width: '144px',
              height: '32px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              boxShadow: 'inset 0 1px 3px rgba(255,255,255,0.3), 0 2px 4px rgba(0,0,0,0.2)',
              color: '#000000',
              fontWeight: '900',
              letterSpacing: '1px',
              fontSize: '1.2rem',
              textShadow: 'none',
            }}>
              SPACE
            </div>
            <div style={{
              background: 'linear-gradient(145deg, #e0e0e0, #d0d0d0)',
              border: '2px solid #999',
              borderRadius: '6px',
              padding: '8px',
              width: '32px',
              height: '32px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              boxShadow: 'inset 0 1px 3px rgba(255,255,255,0.3), 0 2px 4px rgba(0,0,0,0.2)',
              color: '#000000',
              fontWeight: '900',
              letterSpacing: '1px',
              fontSize: '1.1rem',
              textShadow: 'none',
              marginRight: '4px',
            }}>
              Q
            </div>
          </div>

          {/* Text Box - Right Side */}
          <div
            style={{
              color: '#ffffff',
              fontSize: '1.4rem',
              fontWeight: 'bold',
              textShadow: '3px 3px 6px rgba(0, 0, 0, 0.9), 0 0 12px rgba(0, 0, 0, 0.8), 0 0 20px rgba(0, 0, 0, 0.6)',
              lineHeight: '2.2',
              letterSpacing: '0.8px',
              textTransform: 'uppercase',
              display: 'flex',
              flexDirection: 'column',
              gap: '12px',
              minWidth: '140px',
              alignItems: 'flex-start',
            }}
          >
            <div>Move</div>
            <div>Leap</div>
            <div>Auto-attack</div>
          </div>
        </div>
      </div>

      {/* CSS Animations */}
      <style>
        {`
          @keyframes glow {
            0%, 100% { opacity: 0.6; transform: scale(1); }
            50% { opacity: 1; transform: scale(1.1); }
          }
          
          @keyframes fadeInUp {
            from {
              opacity: 0;
              transform: translateY(30px);
            }
            to {
              opacity: 1;
              transform: translateY(0);
            }
          }
          
          @keyframes fadeInDown {
            from {
              opacity: 0;
              transform: translateY(-30px);
            }
            to {
              opacity: 1;
              transform: translateY(0);
            }
          }
          
          .start-button:hover {
            transform: scale(1.05) !important;
            text-shadow: 0 4px 16px rgba(0,0,0,0.9), 0 0 30px rgba(255,255,255,0.8) !important;
          }
        `}
      </style>
    </div>
  );
};

export default MainMenu;
