import Phaser from "phaser";
import { EnemyType } from "../game/EnemyTypes";

// Extend the EnemyType enum to include Player
export enum EntityType {
  Player = "player",
  Normal = "normal",
  Special = "special",
  Boss = "boss",
}

export interface HealthBarConfig {
  x: number;
  y: number;
  width?: number;
  height?: number;
  maxHp: number;
  currentHp: number;
  armor?: number;
  name?: string;
  showName?: boolean;
  isBoss?: boolean;
  scene: Phaser.Scene;
  entityType?: EntityType; // Changed from enemyType to entityType
  entityColor?: number; // Changed from enemyColor to entityColor
  showHpText?: boolean;
}

export interface EnemyHealthBarConfig {
  x: number;
  y: number;
  width?: number;
  height?: number;
  maxHp: number;
  currentHp: number;
  enemyName: string;
  enemyColor: number;
  scene: Phaser.Scene;
  enemyType?: EnemyType;
  showHpText?: boolean;
}

export interface HealthBarSettings {
  showNormal: boolean;
  showSpecial: boolean;
  showBoss: boolean;
  showPlayer: boolean; // Added player setting
  showNames: boolean;
  showHpText: boolean;
}

export class EnemyHealthBar {
  private scene: Phaser.Scene;
  private hpBar: Phaser.GameObjects.Graphics;
  private nameText?: Phaser.GameObjects.Text;
  private hpText?: Phaser.GameObjects.Text;
  private config: EnemyHealthBarConfig;
  private settings: HealthBarSettings;

  constructor(config: EnemyHealthBarConfig, settings: HealthBarSettings) {
    this.scene = config.scene;
    this.config = config;
    this.settings = settings;

    // Create graphics object for health bar
    this.hpBar = this.scene.add.graphics();
    this.hpBar.setDepth(1100);

    // Create name text if enabled
    if (this.settings.showNames && config.enemyName) {
      this.nameText = this.scene.add.text(
        config.x,
        config.y - 20,
        config.enemyName,
        {
          font: "bold 15px monospace",
          color: "#ffffff",
          align: "center",
          stroke: "#000000",
          strokeThickness: 3,
        }
      );
      this.nameText.setOrigin(0.5, 0.5);
      this.nameText.setDepth(1101);
    }

    // Create HP text if enabled
    if (this.settings.showHpText) {
      this.hpText = this.scene.add.text(
        config.x,
        config.y + 3,
        `${Math.max(0, Math.round(config.currentHp))}`,
        {
          font: "12px monospace",
          color: "#ffffff",
          align: "center",
          stroke: "#000000",
          strokeThickness: 2,
        }
      );
      this.hpText.setOrigin(0.5, 0.5);
      this.hpText.setDepth(1102);
    }

    this.update();
  }

  update(config?: Partial<EnemyHealthBarConfig>, settings?: HealthBarSettings) {
    if (config) {
      this.config = { ...this.config, ...config };
    }
    if (settings) {
      this.settings = settings;
    }

    const {
      x,
      y,
      width = 60,
      height = 6,
      maxHp,
      currentHp,
      enemyName,
      enemyColor,
      enemyType,
    } = this.config;

    // Check if this enemy type should show health bars
    if (enemyType) {
      const shouldShow =
        (enemyType === EnemyType.Normal && this.settings.showNormal) ||
        (enemyType === EnemyType.Special && this.settings.showSpecial) ||
        (enemyType === EnemyType.Boss && this.settings.showBoss);

      if (!shouldShow) {
        this.setVisible(false);
        return;
      }
    }

    // Update name text
    if (this.nameText) {
      this.nameText.setPosition(x, y - 20);
      this.nameText.setText(enemyName);
      this.nameText.setVisible(this.settings.showNames);
    }

    // Update HP text
    if (this.hpText) {
      this.hpText.setPosition(x, y + height / 2);
      this.hpText.setText(`${Math.max(0, Math.round(currentHp))}`);
      this.hpText.setVisible(this.settings.showHpText);
    }

    // Clear previous drawings
    this.hpBar.clear();

    // Draw black background
    this.hpBar.fillStyle(0x000000, 0.85);
    this.hpBar.fillRect(x - width / 2, y, width, height);

    // Draw HP value with enemy color
    const hpRatio = Math.max(0, Math.min(1, currentHp / maxHp));
    this.hpBar.fillStyle(enemyColor, 1);
    this.hpBar.fillRect(x - width / 2, y, width * hpRatio, height);

    // Draw border
    this.hpBar.lineStyle(1, 0x222222, 0.7);
    this.hpBar.strokeRect(x - width / 2, y, width, height);

    // Show the health bar
    this.setVisible(true);
  }

  destroy() {
    this.hpBar.destroy();
    if (this.nameText) this.nameText.destroy();
    if (this.hpText) this.hpText.destroy();
  }

  setVisible(visible: boolean) {
    this.hpBar.setVisible(visible);
    if (this.nameText)
      this.nameText.setVisible(visible && this.settings.showNames);
    if (this.hpText)
      this.hpText.setVisible(visible && this.settings.showHpText);
  }
}

export class HealthBarManager {
  private scene: Phaser.Scene;
  private hpBar: Phaser.GameObjects.Graphics;
  private armorBar: Phaser.GameObjects.Graphics;
  private nameText?: Phaser.GameObjects.Text;
  private crownIcon?: Phaser.GameObjects.Text;
  private hpText?: Phaser.GameObjects.Text;
  private config: HealthBarConfig;
  private settings: HealthBarSettings;

  constructor(config: HealthBarConfig, settings: HealthBarSettings) {
    this.scene = config.scene;
    this.config = config;
    this.settings = settings;

    // Create graphics objects
    this.hpBar = this.scene.add.graphics();
    this.hpBar.setDepth(1100); // Higher than segment depths

    this.armorBar = this.scene.add.graphics();
    this.armorBar.setDepth(1100); // Higher than segment depths

    // Create name text if needed
    if (config.showName && config.name && this.settings.showNames) {
      this.nameText = this.scene.add.text(
        config.x,
        config.y - 15,
        config.name,
        {
          font: "bold 12px monospace",
          color: "#ffffff",
          align: "center",
          stroke: "#000000",
          strokeThickness: 3,
        }
      );
      this.nameText.setOrigin(0.5, 0.5);
      this.nameText.setDepth(1101);

      // Create crown icon for boss enemies
      if (config.isBoss) {
        this.crownIcon = this.scene.add.text(config.x, config.y - 30, "👑", {
          font: "16px Arial",
          color: "#ffd700",
          align: "center",
          stroke: "#000000",
          strokeThickness: 2,
        });
        this.crownIcon.setOrigin(0.5, 0.5);
        this.crownIcon.setDepth(1101);
      }
    }

    // Create HP text if enabled
    if (this.settings.showHpText) {
      this.hpText = this.scene.add.text(
        config.x,
        config.y + (config.height || 8) / 2,
        `${Math.max(0, Math.round(config.currentHp))}`,
        {
          font: "bold 10px monospace",
          color: "#ffffff",
          align: "center",
          stroke: "#000000",
          strokeThickness: 2,
        }
      );
      this.hpText.setOrigin(0.5, 0.5);
      this.hpText.setDepth(1102); // Higher than segment depths
    }

    this.update();
  }

  update(config?: Partial<HealthBarConfig>, settings?: HealthBarSettings) {
    if (config) {
      this.config = { ...this.config, ...config };
    }
    if (settings) {
      this.settings = settings;
    }

    const {
      x,
      y,
      width = 120,
      height = 8,
      maxHp,
      currentHp,
      armor = 0,
      entityType,
    } = this.config;

    // Check if this entity type should show health bars
    if (entityType) {
      let shouldShow = false;

      if (entityType === EntityType.Player) {
        shouldShow = this.settings.showPlayer;
      } else {
        // Handle enemy types (backward compatibility)
        const enemyType = entityType as any as EnemyType;
        shouldShow =
          (enemyType === EnemyType.Normal && this.settings.showNormal) ||
          (enemyType === EnemyType.Special && this.settings.showSpecial) ||
          (enemyType === EnemyType.Boss && this.settings.showBoss);
      }

      if (!shouldShow) {
        this.setVisible(false);
        return;
      }
    }

    // Update name text position if it exists
    if (this.nameText && this.config.showName) {
      this.nameText.setPosition(x, y - 15);
      this.nameText.setText(this.config.name || "");
      this.nameText.setVisible(this.settings.showNames);

      // Update crown icon position if it exists
      if (this.crownIcon && this.config.isBoss) {
        this.crownIcon.setPosition(x, y - 30);
        this.crownIcon.setVisible(this.settings.showNames);
      }
    }

    // Clear previous drawings
    this.hpBar.clear();
    this.armorBar.clear();

    // Drawing health bar

    // HP BAR
    // Draw black background
    this.hpBar.fillStyle(0x000000, 0.85);
    this.hpBar.fillRect(x - width / 2, y, width, height);

    // Draw HP value using entity color
    const hpRatio = Math.max(0, Math.min(1, currentHp / maxHp));
    const entityColor = this.config.entityColor || 0xff4444; // Use entity color or default red
    this.hpBar.fillStyle(entityColor, 1);
    this.hpBar.fillRect(x - width / 2, y, width * hpRatio, height);

    // HP bar drawn successfully

    // Draw border
    this.hpBar.lineStyle(1, 0x222222, 0.7); // Subtle dark border
    this.hpBar.strokeRect(x - width / 2, y, width, height);

    // Draw dividers every 1000 HP for enemies, every 250 HP for players
    const dividerInterval = entityType === EntityType.Player ? 250 : 1000;
    for (let i = dividerInterval; i < maxHp; i += dividerInterval) {
      const dividerX = x - width / 2 + (i / maxHp) * width;
      this.hpBar.lineStyle(1, 0x000000, 0.8); // black, 80% transparency
      this.hpBar.beginPath();
      this.hpBar.moveTo(dividerX, y);
      this.hpBar.lineTo(dividerX, y + height);
      this.hpBar.strokePath();
    }

    // ARMOR BAR (drawn directly below HP, no spacing)
    if (armor > 0) {
      const armorBarHeight = height / 2;
      const armorY = y + height; // no spacing

      // Draw black background
      this.armorBar.fillStyle(0x000000, 0.85);
      this.armorBar.fillRect(x - width / 2, armorY, width, armorBarHeight);

      // Draw armor value
      const armorRatio = Math.max(0, Math.min(1, armor / 100));
      this.armorBar.fillStyle(0xffffff, 1); // white
      this.armorBar.fillRect(
        x - width / 2,
        armorY,
        width * armorRatio,
        armorBarHeight
      );

      // Draw border
      this.armorBar.lineStyle(1, 0x222222, 0.7);
      this.armorBar.strokeRect(x - width / 2, armorY, width, armorBarHeight);

      // Draw divider at 100 armor if armor > 100
      if (armor > 100) {
        const dividerX = x - width / 2 + width; // 100% of width
        this.armorBar.lineStyle(1, 0x000000, 0.8); // black, 80% transparency
        this.armorBar.beginPath();
        this.armorBar.moveTo(dividerX, armorY);
        this.armorBar.lineTo(dividerX, armorY + armorBarHeight);
        this.armorBar.strokePath();
      }
    }

    // Update HP text if it exists
    if (this.hpText) {
      this.hpText.setPosition(x, y + height / 2);
      this.hpText.setText(`${Math.max(0, Math.round(currentHp))}`);
      this.hpText.setVisible(this.settings.showHpText);
    }

    // Show the health bar
    this.setVisible(true);

    // Removed test rectangle - health bar is working correctly
  }

  destroy() {
    this.hpBar.destroy();
    this.armorBar.destroy();
    if (this.nameText) {
      this.nameText.destroy();
    }
    if (this.crownIcon) {
      this.crownIcon.destroy();
    }
    if (this.hpText) {
      this.hpText.destroy();
    }
  }

  setVisible(visible: boolean) {
    this.hpBar.setVisible(visible);
    this.armorBar.setVisible(visible);
    if (this.nameText) {
      this.nameText.setVisible(visible && this.settings.showNames);
    }
    if (this.crownIcon) {
      this.crownIcon.setVisible(visible && this.settings.showNames);
    }
    if (this.hpText) {
      this.hpText.setVisible(visible && this.settings.showHpText);
    }
  }
}
