import React, { useState, useEffect } from 'react';

interface ControlsOverlayProps {
  isVisible: boolean;
  onComplete: () => void;
}

const ControlsOverlay: React.FC<ControlsOverlayProps> = ({ isVisible, onComplete }) => {
  const [shouldShow, setShouldShow] = useState(false);

  useEffect(() => {
    if (isVisible) {
      // Show immediately
      setShouldShow(true);
      
      // Hide after 6 seconds
      const timer = setTimeout(() => {
        setShouldShow(false);
        onComplete();
      }, 6000);

      return () => clearTimeout(timer);
    } else {
      setShouldShow(false);
    }
  }, [isVisible, onComplete]);

  if (!shouldShow) return null;

  const squareButtonStyle = {
    background: 'linear-gradient(145deg, #e0e0e0, #d0d0d0)',
    border: '2px solid #999',
    borderRadius: '6px',
    padding: '8px',
    width: '32px',
    height: '32px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    boxShadow: 'inset 0 1px 3px rgba(255,255,255,0.3), 0 2px 4px rgba(0,0,0,0.2)',
    color: '#000000',
    fontWeight: '900',
    letterSpacing: '1px',
    fontSize: '1.1rem',
    textShadow: 'none',
    marginRight: '4px',
  };

  const spacebarButtonStyle = {
    background: 'linear-gradient(145deg, #e0e0e0, #d0d0d0)',
    border: '2px solid #999',
    borderRadius: '6px',
    padding: '6px 12px',
    width: '144px', // 4 buttons * 32px + 3 gaps * 4px = 128 + 16 = 144px
    height: '32px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    boxShadow: 'inset 0 1px 3px rgba(255,255,255,0.3), 0 2px 4px rgba(0,0,0,0.2)',
    color: '#000000',
    fontWeight: '900',
    letterSpacing: '1px',
    fontSize: '1.2rem',
    textShadow: 'none',
  };

  return (
    <div
      style={{
        position: 'fixed',
        left: '60px',
        top: '50%',
        transform: 'translateY(-50%)',
        zIndex: 1000,
        pointerEvents: 'none',
        opacity: 1,
        animation: 'fadeOut 2s ease-out 4s forwards',
      }}
    >
      <style>
        {`
          @keyframes fadeOut {
            from { opacity: 1; }
            to { opacity: 0; }
          }
        `}
      </style>
      <div
        style={{
          display: 'flex',
          gap: '24px',
          alignItems: 'flex-start',
        }}
      >
        {/* Button Box - Left Side */}
        <div
          style={{
            display: 'flex',
            flexDirection: 'column',
            gap: '12px',
            alignItems: 'flex-end',
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center' }}>
            <div style={squareButtonStyle}>W</div>
            <div style={squareButtonStyle}>A</div>
            <div style={squareButtonStyle}>S</div>
            <div style={squareButtonStyle}>D</div>
          </div>
          <div style={spacebarButtonStyle}>
            SPACE
          </div>
          <div style={squareButtonStyle}>
            Q
          </div>
        </div>

        {/* Text Box - Right Side */}
        <div
          style={{
            color: '#ffffff',
            fontSize: '1.4rem',
            fontWeight: 'bold',
            textShadow: '3px 3px 6px rgba(0, 0, 0, 0.9), 0 0 12px rgba(0, 0, 0, 0.8), 0 0 20px rgba(0, 0, 0, 0.6)',
            lineHeight: '2.2',
            letterSpacing: '0.8px',
            textTransform: 'uppercase',
            display: 'flex',
            flexDirection: 'column',
            gap: '12px',
            minWidth: '140px',
            alignItems: 'flex-start',
          }}
        >
          <div>Move</div>
          <div>Leap</div>
          <div>Auto-attack</div>
        </div>
      </div>
    </div>
  );
};

export default ControlsOverlay;
