import Phaser from 'phaser';

/**
 * ZoomManager handles camera zoom functionality with smooth transitions
 * and overlay rendering for zoom out scenarios.
 */
export class ZoomManager {
  private scene: Phaser.Scene;
  private camera: Phaser.Cameras.Scene2D.Camera | null = null;
  private zoomLevel: number = 1.0;
  private minZoom: number = 0.1;
  private maxZoom: number = 3.0;
  private zoomSpeed: number = 0.15; // Slightly smaller steps for smoother mouse wheel control
  private overlayGraphics: Phaser.GameObjects.Graphics | null = null;
  private isZooming: boolean = false;
  private targetZoom: number = 1.0;
  private zoomTransitionSpeed: number = 0.02;

  constructor(scene: Phaser.Scene) {
    this.scene = scene;
    // Don't initialize camera/graphics here - they might not be available yet
  }

  /**
   * Initialize the zoom manager (call this from scene's create method)
   */
  initialize(): void {
    this.camera = this.scene.cameras.main;
    this.overlayGraphics = this.scene.add.graphics();
    this.overlayGraphics.setDepth(1000); // Very high depth to appear above everything
    this.setupKeys();
  }

  /**
   * Get the camera, initializing if necessary
   */
  private getCamera(): Phaser.Cameras.Scene2D.Camera {
    if (!this.camera) {
      this.camera = this.scene.cameras.main;
    }
    return this.camera;
  }

  /**
   * Get the overlay graphics, initializing if necessary
   */
  private getOverlayGraphics(): Phaser.GameObjects.Graphics {
    if (!this.overlayGraphics) {
      this.overlayGraphics = this.scene.add.graphics();
      this.overlayGraphics.setDepth(10000); // Very high depth to ensure it's above everything
    }
    return this.overlayGraphics;
  }

  /**
   * Set up keyboard controls for zoom
   */
  private setupKeys(): void {
    // Set up mouse wheel for zoom controls
    this.scene.input.on('wheel', (pointer: Phaser.Input.Pointer, gameObjects: Phaser.GameObjects.GameObject[], deltaX: number, deltaY: number, deltaZ: number) => {
      // Prevent default browser scrolling when over the game canvas
      if (pointer.event) {
        pointer.event.preventDefault();
      }

      // deltaY is negative when scrolling up (zoom in), positive when scrolling down (zoom out)
      if (deltaY < 0) {
        this.zoomIn();
      } else if (deltaY > 0) {
        this.zoomOut();
      }
    });

    // Keep keyboard reset as backup (0 key)
    this.scene.input.keyboard?.on('keydown-ZERO', () => {
      this.resetZoom();
    });
  }

  /**
   * Zoom in by one step
   */
  zoomIn(): void {
    const newZoom = Math.min(this.zoomLevel + this.zoomSpeed, this.maxZoom);
    this.setTargetZoom(newZoom);
  }

  /**
   * Zoom out by one step
   */
  zoomOut(): void {
    const newZoom = Math.max(this.zoomLevel - this.zoomSpeed, this.minZoom);
    this.setTargetZoom(newZoom);
  }

  /**
   * Reset zoom to default level
   */
  resetZoom(): void {
    this.setTargetZoom(1.0);
  }

  /**
   * Set target zoom level with smooth transition
   */
  setTargetZoom(targetZoom: number): void {
    this.targetZoom = Phaser.Math.Clamp(targetZoom, this.minZoom, this.maxZoom);
    this.isZooming = true;
  }

  /**
   * Update zoom transition and overlay rendering
   */
  update(delta: number): void {
    // Handle smooth zoom transition
    if (this.isZooming) {
      const zoomDiff = this.targetZoom - this.zoomLevel;
      const step = this.zoomTransitionSpeed * delta;

      if (Math.abs(zoomDiff) < step) {
        this.zoomLevel = this.targetZoom;
        this.isZooming = false;
      } else {
        this.zoomLevel += Math.sign(zoomDiff) * step;
      }

      this.getCamera().setZoom(this.zoomLevel);
    }

    // Update overlay for zoom out
    this.updateOverlay();
  }

  /**
   * Render dark overlay when zoomed out beyond screen size
   */
  private updateOverlay(): void {
    const graphics = this.getOverlayGraphics();
    graphics.clear();

    if (this.zoomLevel < 1.0) {
      const camera = this.getCamera();
      const screenWidth = camera.width;
      const screenHeight = camera.height;

      // Calculate the original screen area (when zoom was 1.0)
      const originalWidth = screenWidth;
      const originalHeight = screenHeight;

      // Make overlay much more generous - extend far beyond screen bounds
      const overlayMargin = Math.max(screenWidth, screenHeight) * 2; // Much larger margin

      const overlayAlpha = Math.min(0.8, (1.0 - this.zoomLevel) * 1.2);

      // Calculate screen boundaries in world coordinates
      const screenLeft = camera.scrollX;
      const screenRight = camera.scrollX + screenWidth;
      const screenTop = camera.scrollY;
      const screenBottom = camera.scrollY + screenHeight;

      // Draw overlay as FOUR separate rectangles around the screen (leaving center clear)
      graphics.fillStyle(0x000000, overlayAlpha);

      // Top rectangle (extends far above the screen)
      const topHeight = overlayMargin;
      graphics.fillRect(
        screenLeft - overlayMargin,
        screenTop - overlayMargin,
        screenWidth + (overlayMargin * 2),
        topHeight
      );

      // Bottom rectangle (extends far below the screen)
      const bottomHeight = overlayMargin;
      graphics.fillRect(
        screenLeft - overlayMargin,
        screenBottom,
        screenWidth + (overlayMargin * 2),
        bottomHeight
      );

      // Left rectangle (extends far to the left, excluding top/bottom areas)
      const leftWidth = overlayMargin;
      graphics.fillRect(
        screenLeft - overlayMargin,
        screenTop,
        leftWidth,
        screenHeight
      );

      // Right rectangle (extends far to the right, excluding top/bottom areas)
      const rightWidth = overlayMargin;
      graphics.fillRect(
        screenRight,
        screenTop,
        rightWidth,
        screenHeight
      );

      // Draw bright border around the original screen area
      graphics.lineStyle(3, 0xffffff, 0.8);
      graphics.strokeRect(screenLeft, screenTop, screenWidth, screenHeight);

      // Add corner markers for the original screen boundaries (scaled by zoom level)
      const cornerSize = Math.max(15, 25 / this.zoomLevel); // Scale corner size with zoom
      graphics.fillStyle(0xffffff, 0.9);

      // Top-left corner marker
      graphics.fillRect(screenLeft, screenTop, cornerSize, 3);
      graphics.fillRect(screenLeft, screenTop, 3, cornerSize);

      // Top-right corner marker
      graphics.fillRect(screenRight - cornerSize, screenTop, cornerSize, 3);
      graphics.fillRect(screenRight - 3, screenTop, 3, cornerSize);

      // Bottom-left corner marker
      graphics.fillRect(screenLeft, screenBottom - 3, cornerSize, 3);
      graphics.fillRect(screenLeft, screenBottom - cornerSize, 3, cornerSize);

      // Bottom-right corner marker
      graphics.fillRect(screenRight - cornerSize, screenBottom - 3, cornerSize, 3);
      graphics.fillRect(screenRight - 3, screenBottom - cornerSize, 3, cornerSize);
    }
  }

  /**
   * Get current zoom level
   */
  getZoomLevel(): number {
    return this.zoomLevel;
  }

  /**
   * Check if camera is currently zooming
   */
  isCurrentlyZooming(): boolean {
    return this.isZooming;
  }

  /**
   * Get zoom bounds
   */
  getZoomBounds(): { min: number, max: number } {
    return { min: this.minZoom, max: this.maxZoom };
  }

  /**
   * Destroy the zoom manager and clean up resources
   */
  destroy(): void {
    if (this.overlayGraphics) {
      this.overlayGraphics.destroy();
    }
    // Remove key listeners (Phaser handles this automatically when scene is destroyed)
  }
}
