import { SegmentedEntity } from "./SegmentedEntity";

// Tail enemy - segments dangle behind a master entity

export class TailEnemy extends SegmentedEntity {
  masterSpeed: number = 1.2;
  tailLoose: number = 0.3; // How loose the tail follows (0 = tight, 1 = very loose)

  constructor() {
    const segmentRadius = 10;

    super(
      "tail",
      8, // 8 segments (body + 7 tail)
      segmentRadius, // segment radius
      0xaa8844, // brown color
      35, // hp
      5, // armor
      1.0, // move speed
      6, // attack damage
      0.6, // attack speed
      150, // attack range
      2, // magic resist
      0, // magic power
      0, // cooldown
      1.0, // aoe
      4, // projectile speed
      1.0, // projectile scale
      0, // burst fire
      0, // crit chance
      0, // crit level
      0, // lifesteal
      0, // regen
      0, // evasion
      1, // xp boost
      1, // magnet
      0, // luck
      1 // gold find
    );
  }

  // Override to use 2x radius spacing for tail segments
  getSegmentSpacing(previousSegmentIndex: number): number {
    const previousRadius =
      previousSegmentIndex >= 0
        ? this.getSegmentRadius(previousSegmentIndex)
        : this.segmentRadius;
    return previousRadius * 2; // 2x radius spacing for tail
  }

  // Override for more loose tail movement
  getSegmentTarget(
    index: number,
    currentTime: number
  ): { x: number; y: number; shouldBeVisible: boolean } {
    // The last segment in the array is the master (body), so we need to reverse the logic
    const isMaster = index === this.segments.length - 1;

    if (isMaster) {
      // Master segment (body) moves normally
      return {
        x: this.master!.targetX,
        y: this.master!.targetY,
        shouldBeVisible: true,
      };
    }

    // Tail segments have more loose following with delay based on distance from master
    const distanceFromMaster = this.segments.length - 1 - index;
    const delayTime = distanceFromMaster * 150; // Longer delay for tail
    const targetTime = currentTime - delayTime;

    let targetPoint = this.pathHistory[0];
    for (let i = this.pathHistory.length - 1; i >= 0; i--) {
      if (this.pathHistory[i].time <= targetTime) {
        targetPoint = this.pathHistory[i];
        break;
      }
    }

    // Add some randomness for loose tail effect
    const randomOffset = this.tailLoose * 10;
    const randomX = targetPoint.x + (Math.random() - 0.5) * randomOffset;
    const randomY = targetPoint.y + (Math.random() - 0.5) * randomOffset;

    return { x: randomX, y: randomY, shouldBeVisible: true };
  }
}
