import { BehaviorManager } from "../behaviours/BehaviorManager";
import { Segment } from "./Segment";
import { CircleBehavior } from "../behaviours/CircleBehavior";
import { SegmentedEntity } from "./SegmentedEntity";

// Dragon enemy classes

export class SolarDragonEnemy extends SegmentedEntity {
  behaviorManager: BehaviorManager;

  constructor(
    hp: number,
    armor: number,
    moveSpeed: number,
    attackDamage: number,
    attackSpeed: number,
    attackRange: number,
    magicResist: number,
    magicPower: number,
    evasion: number,
    xp: number,
    projectileScale: number,
    projectileSpeed: number
  ) {
    super(
      "solar_dragon",
      25, // 25 segments for solar dragon
      95, // segment radius (match enemy radius)
      0xff4500, // orange red color
      hp,
      armor,
      moveSpeed,
      attackDamage,
      attackSpeed,
      attackRange,
      magicResist,
      magicPower,
      0,
      0,
      0,
      0,
      0,
      0,
      0,
      0,
      0,
      evasion,
      1,
      1,
      0,
      1,
      false
    );

    this.behaviorManager = new BehaviorManager(
      new CircleBehavior(this.attackRange, this.moveSpeed, 600, 0.1, true, true)
    );
  }

  // Override to create a color gradient from orange-red head to yellow tail
  initializeSegments(scene: any, startX: number, startY: number) {
    this.segments = [];

    // Create initial path history - a straight line behind the start position
    this.pathHistory = [];
    const currentTime = scene.time.now;

    // Calculate cumulative spacing for each segment
    let cumulativeSpacing = 0;
    const segmentSpacings: number[] = [];

    for (let i = 0; i < this.segmentCount; i++) {
      if (i === 0) {
        // First segment (head) has no spacing
        segmentSpacings.push(0);
      } else {
        // Each subsequent segment uses spacing based on previous segment's radius
        const spacing = this.getSegmentSpacing(i - 1);
        cumulativeSpacing += spacing;
        segmentSpacings.push(cumulativeSpacing);
      }
    }

    // Create path points going backwards from the start position
    for (let i = 0; i < this.segmentCount; i++) {
      const distanceFromStart = segmentSpacings[i];
      const pathPoint = {
        x: startX - distanceFromStart, // Go backwards in a straight line (so segments appear behind)
        y: startY,
        time: currentTime - i * 100, // Each point slightly older than the next
      };
      this.pathHistory.push(pathPoint); // Add to end to maintain chronological order (oldest first)
    }

    // Create body segments first (drawn behind) with gradient from orange-red to yellow
    // Positioned along the initial path
    for (let i = this.segmentCount - 1; i > 0; i--) {
      // Create gradient from orange-red (0xFF4500) to lighter orange (0xFF6633)
      const progress = 1 - i / (this.segmentCount - 1); // Inverted: 1 to 0 (dark to light)
      const orangeRed = 0xff4500;
      const lightOrange = 0xff6633;

      // Interpolate between orange-red and light orange
      const r1 = (orangeRed >> 16) & 0xff;
      const g1 = (orangeRed >> 8) & 0xff;
      const b1 = orangeRed & 0xff;

      const r2 = (lightOrange >> 16) & 0xff;
      const g2 = (lightOrange >> 8) & 0xff;
      const b2 = lightOrange & 0xff;

      const r = Math.floor(r1 + (r2 - r1) * progress);
      const g = Math.floor(g1 + (g2 - g1) * progress);
      const b = Math.floor(b1 + (b2 - b1) * progress);

      const segmentColor = (r << 16) | (g << 8) | b;

      // Get the radius for this specific segment
      const segmentRadius = this.getSegmentRadius(i);

      // Position segment along the initial path
      // Since pathHistory is oldest first, we need to access from the end
      const pathIndex = this.pathHistory.length - 1 - i; // Reverse the indexing
      const pathPoint = this.pathHistory[pathIndex];

      const segment = new Segment(
        pathPoint.x,
        pathPoint.y,
        segmentRadius,
        segmentColor,
        false
      );
      segment.setVisible(true); // All segments visible from start
      this.segments.push(segment);
    }

    // Create the master segment (head) at the end
    const masterRadius = this.getSegmentRadius(this.segmentCount - 1);
    const masterSegment = new Segment(
      startX,
      startY,
      masterRadius,
      0xff4500, // Orange-red head
      true
    );
    masterSegment.setVisible(true);
    this.master = masterSegment;
    this.segments.push(masterSegment);
  }
}
