// Segment class for individual parts of segmented entities

export class Segment {
  sprite?: Phaser.GameObjects.GameObject;
  targetX: number = 0;
  targetY: number = 0;
  currentX: number = 0;
  currentY: number = 0;
  isMaster: boolean = false;
  radius: number;
  color: number;
  tweenSpeed: number = 0.15; // Smoothing factor for movement
  isVisible: boolean = false; // Whether this segment should be rendered

  constructor(
    x: number,
    y: number,
    radius: number,
    color: number,
    isMaster: boolean = false
  ) {
    this.targetX = x;
    this.targetY = y;
    this.currentX = x;
    this.currentY = y;
    this.radius = radius;
    this.color = color;
    this.isMaster = isMaster;
    this.isVisible = isMaster; // Master segment is always visible
  }

  updatePosition(x: number, y: number) {
    this.targetX = x;
    this.targetY = y;
  }

  // Smooth movement towards target position
  updateSmoothPosition() {
    this.currentX += (this.targetX - this.currentX) * this.tweenSpeed;
    this.currentY += (this.targetY - this.currentY) * this.tweenSpeed;
  }

  // Set visibility for this segment
  setVisible(visible: boolean) {
    this.isVisible = visible;
  }
}
