import { BaseMovementBehavior } from "./BaseMovementBehavior";
import { Enemy } from "../entities/Enemy";

// S-motion behavior: worm follows a sliding point on an imaginary line

export class SMotionBehavior extends BaseMovementBehavior {
  private lineWidth: number;
  private slideSpeed: number;
  private currentTime: number = 0;
  private amplitude: number = 200; // Half the line width

  constructor(
    attackRange: number,
    moveSpeed: number,
    lineWidth: number = 400,
    slideSpeed: number = 2,
    canAttackWhileMoving: boolean = true
  ) {
    super(attackRange, moveSpeed, canAttackWhileMoving);
    this.lineWidth = lineWidth;
    this.slideSpeed = slideSpeed;
  }

  update(
    enemy: Enemy,
    playerX: number,
    playerY: number,
    deltaTime: number
  ): { targetX: number; targetY: number; shouldAttack: boolean } {
    const shouldAttack = this.shouldAttack(enemy, playerX, playerY);

    // Update time for sine wave
    this.currentTime += deltaTime / 1000; // Convert to seconds

    // Calculate the midpoint between player and worm
    const midX = (playerX + enemy.x) / 2;
    const midY = (playerY + enemy.y) / 2;

    // Calculate the direction from worm to player
    const directionX = playerX - enemy.x;
    const directionY = playerY - enemy.y;
    const distance = Math.sqrt(
      directionX * directionX + directionY * directionY
    );

    // Normalize the direction
    const normalizedDirX = directionX / distance;
    const normalizedDirY = directionY / distance;

    // Calculate perpendicular direction (90 degrees) for the line
    const perpX = -normalizedDirY;
    const perpY = normalizedDirX;

    // Calculate the sliding point using sine wave
    const sineOffset =
      Math.sin(this.currentTime * this.slideSpeed) * this.amplitude;

    // Position the sliding point on the imaginary line
    const slidingPointX = midX + perpX * sineOffset;
    const slidingPointY = midY + perpY * sineOffset;

    return { targetX: slidingPointX, targetY: slidingPointY, shouldAttack };
  }

  getType(): string {
    return "s-motion";
  }
}
