import { Scene } from 'phaser';

export interface PickupConfig {
  x: number;
  y: number;
  value: number;
  color: number;
  radius?: number;
  age?: number;
  isBossPickup?: boolean;
  magnetRange?: number;
  moveSpeed?: number;
  despawnTime?: number;
  collectionRange?: number;
  shape?: 'circle' | 'hexagon';
}

export abstract class Pickup {
  protected scene: Scene;
  protected sprite: Phaser.GameObjects.Arc | Phaser.GameObjects.Polygon;
  protected config: PickupConfig;
  protected age: number = 0;

  constructor(scene: Scene, config: PickupConfig) {
    this.scene = scene;
    this.config = {
      radius: 2.5,
      age: 0,
      isBossPickup: false,
      magnetRange: 0,
      moveSpeed: 14,
      despawnTime: 20000,
      collectionRange: 24,
      ...config
    };
    
    // Create hexagonal or circular sprite based on config
    if (config.shape === 'hexagon') {
      // Create hexagonal shape
      const radius = this.config.radius!;
      const points = [];
      for (let i = 0; i < 6; i++) {
        const angle = (i * Math.PI) / 3;
        points.push({
          x: Math.cos(angle) * radius,
          y: Math.sin(angle) * radius
        });
      }
      this.sprite = scene.add.polygon(config.x, config.y, points, config.color);
      // Add a glow effect to make it more visible
      (this.sprite as any).setStrokeStyle(2, 0xffff00, 1);
    } else {
      // Create circular shape (default)
      this.sprite = scene.add.circle(
        config.x, 
        config.y, 
        this.config.radius!, 
        config.color
      );
    }
    
    // Add pickup-specific properties to the sprite
    (this.sprite as any).pickup = this;
    (this.sprite as any).value = config.value;
    (this.sprite as any).orbAge = this.config.age;
    (this.sprite as any).isBossOrb = this.config.isBossPickup;
  }

  public getSprite(): Phaser.GameObjects.Arc | Phaser.GameObjects.Polygon {
    return this.sprite;
  }

  public getValue(): number {
    return this.config.value;
  }

  public isBossPickup(): boolean {
    return this.config.isBossPickup!;
  }

  public update(scaledDelta: number, player?: Phaser.GameObjects.Arc, playerCharacter?: any): void {
    if (!this.sprite.active) return;

    // Update age
    this.age += scaledDelta;
    (this.sprite as any).orbAge = this.age;

    // Check for despawn
    if (this.age > this.config.despawnTime!) {
      this.destroy();
      return;
    }

    // Handle movement towards player
    this.handleMovement(scaledDelta, player, playerCharacter);

    // Handle collection
    this.handleCollection(player, playerCharacter);
  }

  protected handleMovement(scaledDelta: number, player?: Phaser.GameObjects.Arc, playerCharacter?: any): void {
    if (!player) return;

    const dist = Phaser.Math.Distance.Between(player.x, player.y, this.sprite.x, this.sprite.y);
    
    if (this.config.isBossPickup) {
      // Boss pickups are automatically attracted to player from anywhere
      const angle = Phaser.Math.Angle.Between(this.sprite.x, this.sprite.y, player.x, player.y);
      this.sprite.x += Math.cos(angle) * 8 * (scaledDelta / 16.67);
      this.sprite.y += Math.sin(angle) * 8 * (scaledDelta / 16.67);
      this.sprite.setPosition(this.sprite.x, this.sprite.y);
    } else {
      // Normal pickups use player's magnet range
      let magnetRange = this.config.magnetRange!;
      if (playerCharacter?.magnet) magnetRange = 80 * playerCharacter.magnet;
      if (playerCharacter?.aoe) magnetRange *= playerCharacter.aoe;
      
      if (dist < magnetRange) {
        const angle = Phaser.Math.Angle.Between(this.sprite.x, this.sprite.y, player.x, player.y);
        this.sprite.x += Math.cos(angle) * this.config.moveSpeed! * (scaledDelta / 16.67);
        this.sprite.y += Math.sin(angle) * this.config.moveSpeed! * (scaledDelta / 16.67);
        this.sprite.setPosition(this.sprite.x, this.sprite.y);
      }
    }
  }

  protected handleCollection(player?: Phaser.GameObjects.Arc, playerCharacter?: any): void {
    if (!player) return;

    const dist = Phaser.Math.Distance.Between(player.x, player.y, this.sprite.x, this.sprite.y);
    
    // Debug: Log distance and collection range for gold pickups (uncomment for debugging)
    // if (this.config.shape === 'hexagon') {
    //   console.log('Gold pickup - Distance:', dist, 'Collection range:', this.config.collectionRange);
    // }
    
    if (dist < this.config.collectionRange!) {
      // console.log('Gold pickup collected!');
      this.onCollected(playerCharacter);
      this.destroy();
    }
  }

  protected abstract onCollected(playerCharacter?: any): void;

  public destroy(): void {
    if (this.sprite && this.sprite.active) {
      this.sprite.destroy();
    }
  }

  public isActive(): boolean {
    return this.sprite && this.sprite.active;
  }
}

export class XPPickup extends Pickup {
  constructor(scene: Scene, config: PickupConfig) {
    super(scene, {
      ...config,
      color: config.color || 0x44ffcc, // Default XP orb color
    });
  }

  protected onCollected(playerCharacter?: any): void {
    if (!playerCharacter) return;
    
    let xp = this.config.value;
    if (playerCharacter.xpBoost) {
      xp = Math.floor(xp * (1 + playerCharacter.xpBoost));
    }
    playerCharacter.gainXP(xp);
  }
}

export class GoldPickup extends Pickup {
  constructor(scene: Scene, config: PickupConfig) {
    super(scene, {
      ...config,
      color: config.color || 0xffd700, // Default gold color
      shape: 'hexagon', // Make gold pickups hexagonal
      radius: (config.radius || 2.5) * 3, // Make them 3x bigger
      collectionRange: 30, // Smaller collection range for gold pickups to prevent immediate collection
    });
  }

  protected onCollected(playerCharacter?: any): void {
    if (!playerCharacter) return;
    

    
    // Add gold to player character
    if (playerCharacter.gainGold) {
      playerCharacter.gainGold(this.config.value);
    } else {
      // Fallback: add gold property if it doesn't exist
      playerCharacter.gold = (playerCharacter.gold || 0) + this.config.value;
      console.log('Gold added via direct property. New total:', playerCharacter.gold);
    }
  }
}



